# -------------------------------------------------
# Преобразуем raw_text → список строк
# -------------------------------------------------
lines = [ln.rstrip() for ln in raw_text.split("\n")]

doc = Document()

# Добавляем стили заголовков (опционально)
styles = doc.styles

for line in lines:
    if not line.strip():
        # Пустая строка – новый пустой параграф
        doc.add_paragraph("")
        continue

    # Определяем уровень заголовка по количеству решёток в начале строки
    if line.startswith("# "):
        # Уровень 1 (Title)
        doc.add_heading(line[2:].strip(), level=0)
    elif line.startswith("## "):
        doc.add_heading(line[3:].strip(), level=1)
    elif line.startswith("### "):
        doc.add_heading(line[4:].strip(), level=2)
    elif line.startswith("#### "):
        doc.add_heading(line[5:].strip(), level=3)
    else:
        # Обычный абзац
        p = doc.add_paragraph(line)

# Сохраняем файл
output_path = "senkaku_diaoyu_dispute.docx"
doc.save(output_path)
print(f"Документ сохранён как {output_path}")
